'use strict';
// library/music.js : the music directions a library template may ask the music service for, written the way the
// launch templates write theirs. Recipes name them by tone and by what they are for, never by id; an id is stable for ever.
//   styles   seven style phrases: the genre, the instruments, the feel
//   bpm      60 to 150          voices   who sings and how          notes   one sentence of mood, an image
//   negative what to keep out (the library adds its own standing list on top)
//   energy   low | mid | high          tones    from the library's tone words          genres, for   free words
// The service's rule (SPEC.md, "The song"): a direction never names an artist, a band, a songwriter, a song, an album,
// a show or a lyric, and no brand of instrument either: style words are instruments, genre and feel.
// Culturally flavoured directions name instruments and feel only. Held to its rules by test/libdata.cjs.
var QUIET = ['comedy', 'novelty sound effects', 'dance beat', 'loud drums'];   // every restrained direction
var WORK = ['religious references', 'drinking songs'];                         // every work direction
var SOFT = ['loud drums', 'fast tempo'];                                       // lullabies
function D(id, name, energy, bpm, styles, voices, notes, tones, genres, use, negative) {
  var d = { id: id, name: name, styles: styles, bpm: bpm, voices: voices, notes: notes };
  if (negative) d.negative = negative.slice();
  d.energy = energy; d.tones = tones.split(' '); d.genres = genres.split(', '); d.for = use.split(' ');
  return d;
}
